<?php
declare(strict_types=1);
namespace Norda;
require_once __DIR__.'/core.php';
function e(mixed $s): string {return htmlspecialchars((string)$s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function l(array $d,string $field,string $lang): string {return (string)($d[$field][$lang]??$d[$field]['az']??'');}
function url(string $file): string {return 'https://nordatech.az'.($file==='index.html'?'/':'/'.$file);}
function localizedFile(string $stem,string $lang): string {return $stem.($lang==='az'?'':'.'.$lang).'.html';}
function icon(string $name): string {return '<svg class="icon" aria-hidden="true"><use href="#i-'.e($name).'"/></svg>';}
function categoryCard(array $c,string $lang,array $ui): string {$id=$c['slug'];$href='/products/'.localizedFile($id,$lang);return '<article class="catalog-card" data-category="'.e($id).'" data-group="'.e($c['group']).'" data-tilt><a class="card-media" href="'.e($href).'" tabindex="-1" aria-hidden="true"><img src="/'.e($c['image']).'" alt="'.e(l($c,'image_alt',$lang)?:l($c,'name',$lang)).'" width="600" height="400" loading="lazy"></a><div class="card-copy"><div class="card-meta"><span>'.e($ui[$c['group']]??'IT').'</span>'.icon($c['icon']??'computer').'</div><a class="card-title-link" href="'.e($href).'"><h3>'.e(l($c,'name',$lang)).'</h3>'.icon('up').'</a><p>'.e(l($c,'description',$lang)).'</p><div class="card-actions"><span class="card-count">'.count($c['products']??[]).' '.e($ui['groupCount']??'').'</span><button class="add-button" type="button" data-add="cat|'.e($id).'" aria-pressed="false">'.icon('plus').'<span>'.e($ui['add']??'+').'</span></button></div></div></article>';}
function pageInfo(string $file,array $all,array $seed): ?array {
    foreach($seed['routes']as$route)if($route['file']===$file){$r=$all[$route['record']]??null;if($r&&$r['archived'])return ['gone'=>true];if($r&&$r['published'])return ['record'=>$r,'lang'=>$route['lang'],'base'=>$file];return ['lang'=>$route['lang'],'base'=>$file,'record'=>null];}
    foreach($all as$r){if(!$r['published']||$r['archived'])continue;$d=$r['published'];foreach(['az','en','ru']as$lang){$candidate=match($r['kind']){'category'=>'products/'.localizedFile($d['slug'],$lang),'product'=>'products/'.localizedFile('item-'.$d['slug'],$lang),'article'=>'articles/'.localizedFile($d['slug'],$lang),default=>null};if($candidate===$file)return ['record'=>$r,'lang'=>$lang,'base'=>localizedFile('about',$lang),'new'=>true];}}
    return null;
}
function doc(string $html): array {
