    $d=new \DOMDocument('1.0','UTF-8');$previous=libxml_use_internal_errors(true);$d->loadHTML('<?xml encoding="UTF-8">'.$h,LIBXML_NOERROR|LIBXML_NOWARNING);libxml_clear_errors();libxml_use_internal_errors($previous);return [$d,new \DOMXPath($d),$protected];
}
function cls(string $c): string {return 'contains(concat(" ",normalize-space(@class)," ")," '.$c.' ")';}
