function sitemap(): string {$files=[];foreach(seed()['routes']as$r){$active=true;if(config()){$state=query('SELECT archived,published FROM records WHERE id=?',[$r['record']])->fetch();$active=$state&&!$state['archived']&&$state['published'];}if($active&&!str_starts_with($r['file'],'404'))$files[$r['file']]=true;}if(config()){foreach(['category','product','article']as$kind)foreach(published($kind)as$d)foreach(['az','en','ru']as$l){$file=match($kind){'category'=>'products/'.localizedFile($d['slug'],$l),'product'=>'products/'.localizedFile('item-'.$d['slug'],$l),'article'=>'articles/'.localizedFile($d['slug'],$l)};$files[$file]=true;}}$xml='<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">';foreach(array_keys($files)as$f)$xml.='<url><loc>'.e(url($f)).'</loc></url>';return $xml.'</urlset>';}
